import java.util.*;

public class SetOrderingDemo {
    public static void main(String[] args) {
        List<String> inputs = Arrays.asList("Delta", "Alpha", "Charlie", "Bravo");

        Set<String> hashSet = new HashSet<>(inputs);
        Set<String> linkedHashSet = new LinkedHashSet<>(inputs);
        Set<String> treeSet = new TreeSet<>(inputs);

        System.out.println("HashSet (No guarantee): " + hashSet);
        System.out.println("LinkedHashSet (Insertion order): " + linkedHashSet);
        System.out.println("TreeSet (Sorted order): " + treeSet);
    }
}
